// T7 垂直轮播组件 (已修复自动轮播和滑动定位问题)
// 修改：接收 onCharacterClick 属性
const VerticalCarousel = ({ onCharacterClick }) => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [carouselData, setCarouselData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const touchStartY = useRef(0);
  const autoPlayRef = useRef(null);
  const CACHE_KEY = "celebrity_cards_cache";

  // 加载缓存的名人卡片数据
  useEffect(() => {
    try {
      const cachedData = localStorage.getItem(CACHE_KEY);
      if (cachedData) {
        console.log("加载缓存的名人卡片数据...");
        const parsedData = JSON.parse(cachedData);
        setCarouselData(parsedData);
      } else {
        // 使用默认数据
        console.log("未找到缓存，使用默认名人卡片数据...");
        const defaultData = [
          {
            id: 1,
            name: "广陵王",
            tagLine: "#绣衣校尉有一子",
            subTag: "#广陵公然反对朝许",
            avatarBg: "#FCEFE3",
            iconColor: "#E6B980",
            themeColor: "#FDF6EE",
          },
          {
            id: 2,
            name: "张道陵",
            tagLine: "#五斗米招人",
            subTag: "#益州 反目 铁祖道",
            avatarBg: "#FBE8E8",
            iconColor: "#E88C8C",
            themeColor: "#FEF6F6",
          },
          {
            id: 3,
            name: "袁基",
            tagLine: "#汝南袁氏",
            subTag: "#君子温润如玉",
            avatarBg: "#E8F5E9",
            iconColor: "#81C784",
            themeColor: "#F1F8F1",
          },
        ];
        setCarouselData(defaultData);
        // 缓存默认数据
        localStorage.setItem(CACHE_KEY, JSON.stringify(defaultData));
      }
    } catch (error) {
      console.error("加载缓存失败:", error);
      // 使用默认数据
      const defaultData = [
        {
          id: 1,
          name: "广陵王",
          tagLine: "#绣衣校尉有一子",
          subTag: "#广陵公然反对朝许",
          avatarBg: "#FCEFE3",
          iconColor: "#E6B980",
          themeColor: "#FDF6EE",
        },
        {
          id: 2,
          name: "张道陵",
          tagLine: "#五斗米招人",
          subTag: "#益州 反目 铁祖道",
          avatarBg: "#FBE8E8",
          iconColor: "#E88C8C",
          themeColor: "#FEF6F6",
        },
        {
          id: 3,
          name: "袁基",
          tagLine: "#汝南袁氏",
          subTag: "#君子温润如玉",
          avatarBg: "#E8F5E9",
          iconColor: "#81C784",
          themeColor: "#F1F8F1",
        },
      ];
      setCarouselData(defaultData);
      // 缓存默认数据
      localStorage.setItem(CACHE_KEY, JSON.stringify(defaultData));
    }
  }, []);

  // 刷新名人卡片函数
  const refreshCelebrities = async () => {
    try {
      console.log("开始刷新名人卡片...");
      setIsLoading(true);

      // 检查用户是否配置了API地址
      const apiConfigs = localStorage.getItem("api_configs");
      let apiUrl = "";
      if (apiConfigs) {
        try {
          const configs = JSON.parse(apiConfigs);
          if (configs && configs.length > 0) {
            // 使用用户在API配置页面中选中的配置
            const savedSelectedIndex = localStorage.getItem(
              "selected_api_config_index",
            );
            const selectedIndex = savedSelectedIndex
              ? parseInt(savedSelectedIndex)
              : 0;
            const selectedConfig = configs[selectedIndex] || configs[0];
            apiUrl = selectedConfig.url;
            console.log("从api_configs中读取到API地址:", apiUrl);
          }
        } catch (parseError) {
          console.error("解析api_configs失败:", parseError);
        }
      }

      if (!apiUrl) {
        console.error("未找到用户配置的LLM API地址");
        // 显示错误提示
        alert("请先在设置中配置LLM API地址，否则无法生成新的名人卡片");
        return;
      }

      // 1. 读取热点追踪信息
      console.log("步骤1: 读取热点追踪信息");
      const hotTrackingInfo = getHotTrackingInfo();
      console.log("热点追踪信息:", hotTrackingInfo);

      // 2. 读取世界书信息
      console.log("步骤2: 读取世界书信息");
      const worldBookInfo = getWorldBookInfo();
      console.log("世界书信息:", worldBookInfo);

      // 3. 调用LLM API生成新的名人卡片
      console.log("步骤3: 调用LLM API生成新的名人卡片");
      const newCelebrities = await generateCelebritiesWithLLM(
        hotTrackingInfo,
        worldBookInfo,
      );
      console.log("新生成的名人卡片:", newCelebrities);

      // 4. 更新名人卡片数据
      console.log("步骤4: 更新名人卡片数据");
      setCarouselData(newCelebrities);

      // 5. 更新缓存
      console.log("步骤5: 更新名人卡片缓存");
      localStorage.setItem(CACHE_KEY, JSON.stringify(newCelebrities));

      // 6. 重置轮播索引
      console.log("步骤6: 重置轮播索引");
      setActiveIndex(0);

      console.log("名人卡片刷新完成");
    } catch (error) {
      console.error("刷新名人卡片失败:", error);
      // 显示错误提示
      alert("刷新名人卡片失败: " + error.message);
    } finally {
      setIsLoading(false);
    }
  };

  // 读取热点追踪信息
  const getHotTrackingInfo = () => {
    try {
      const hotPosts = [];
      console.log("开始读取热点追踪信息...");

      // 检查localStorage中是否有热点追踪数据
      console.log("localStorage中的键数量:", localStorage.length);
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        console.log("检查localStorage键:", key);
        if (key && key.startsWith("area_content_")) {
          console.log("找到区域内容:", key);
          const cachedContent = localStorage.getItem(key);
          if (cachedContent) {
            try {
              const parsedContent = JSON.parse(cachedContent);
              console.log("解析区域内容:", parsedContent);
              if (parsedContent.items && Array.isArray(parsedContent.items)) {
                console.log("区域包含", parsedContent.items.length, "个项目");
                parsedContent.items.forEach((item) => {
                  if (item.title && (item.likes || item.comments)) {
                    const hotScore = (item.likes || 0) + (item.comments || 0);
                    hotPosts.push({
                      id: item.id,
                      title: item.title,
                      hotScore: hotScore,
                      likes: item.likes || 0,
                      comments: item.comments || 0,
                      content: item.content || "",
                      date: item.date || "",
                      color: item.color || "",
                      areaContent: parsedContent,
                    });
                    console.log("添加热点帖子:", item.title, "热度:", hotScore);
                  }
                });
              } else {
                console.log("区域内容没有items数组");
              }
            } catch (error) {
              console.error("解析缓存内容失败:", error);
            }
          } else {
            console.log("区域内容为空:", key);
          }
        }
      }

      // 按热度排序
      hotPosts.sort((a, b) => b.hotScore - a.hotScore);
      console.log("热点追踪信息读取完成，共找到", hotPosts.length, "个热点");

      // 只取前5个热点
      return hotPosts.slice(0, 5);
    } catch (error) {
      console.error("获取热点追踪信息失败:", error);
      return [];
    }
  };

  // 读取世界书信息
  const getWorldBookInfo = () => {
    try {
      console.log("开始读取世界书信息...");
      // 这里假设世界书信息存储在localStorage中
      const worldBookData = localStorage.getItem("world_book_data");
      if (worldBookData) {
        console.log("找到世界书数据:", worldBookData);
        try {
          const parsedData = JSON.parse(worldBookData);
          console.log("解析世界书数据:", parsedData);
          return parsedData;
        } catch (parseError) {
          console.error("解析世界书数据失败:", parseError);
          return {};
        }
      } else {
        console.log("未找到世界书信息");
        // 检查是否有其他可能的世界书存储键
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i);
          if (key && (key.includes("world") || key.includes("book"))) {
            console.log("找到可能的世界书相关键:", key);
          }
        }
        return {};
      }
    } catch (error) {
      console.error("获取世界书信息失败:", error);
      return {};
    }
  };

  // 调用LLM API生成名人卡片
  const generateCelebritiesWithLLM = async (hotTrackingInfo, worldBookInfo) => {
    return new Promise((resolve, reject) => {
      try {
        console.log("开始调用LLM API生成名人卡片...");

        // 构建系统提示和用户提示
        const systemPrompt =
          "你是一个话题名人分析专家，擅长根据热点追踪信息和世界书信息生成符合当前热点的名人卡片。";

        // 构建用户提示，包含热点追踪和世界书信息
        let userPrompt = `
                                                                                                                        【指令】
                                                                                                                        基于提供的热点追踪信息和世界书信息，生成3个新的话题名人卡片。每个卡片需要包含：id、name（名人名称）、tagLine（标签行）、subTag（子标签）、avatarBg（头像背景色，十六进制颜色）、iconColor（图标颜色，十六进制颜色）、themeColor（主题颜色，十六进制颜色）。请返回JSON格式的数据，确保颜色格式正确。

                                                                                                                        【热点追踪信息】
                                                                                                                        ${JSON.stringify(hotTrackingInfo, null, 2)}

                                                                                                                        【世界书信息】
                                                                                                                        ${JSON.stringify(worldBookInfo, null, 2)}

                                                                                                                        【输出格式严格要求】
                                                                                                                        请仅输出一个JSON格式的数组，不要包含Markdown代码块标记或其他文字。格式如下：
                                                                                                                        [
                                                                                                                          { "id": 1, "name": "名人名称1", "tagLine": "#标签1", "subTag": "#子标签1", "avatarBg": "#FFFFFF", "iconColor": "#000000", "themeColor": "#F0F0F0" },
                                                                                                                          { "id": 2, "name": "名人名称2", "tagLine": "#标签2", "subTag": "#子标签2", "avatarBg": "#FFFFFF", "iconColor": "#000000", "themeColor": "#F0F0F0" },
                                                                                                                          { "id": 3, "name": "名人名称3", "tagLine": "#标签3", "subTag": "#子标签3", "avatarBg": "#FFFFFF", "iconColor": "#000000", "themeColor": "#F0F0F0" }
                                                                                                                        ]
                                                                                                                                  `;

        console.log("构建API请求...");

        // 使用window.sendToLLM函数调用API
        if (window.sendToLLM) {
          console.log("使用window.sendToLLM调用API...");

          const messages = [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ];

          window.sendToLLM(
            messages,
            null, // 非流式调用
            (reply) => {
              try {
                console.log("API响应结果:", reply);

                // 清理可能的markdown标记
                const cleanJson = reply.replace(/```json|```/g, "").trim();

                // 解析JSON响应
                const result = JSON.parse(cleanJson);
                console.log("解析后的名人卡片数据:", result);

                // 确保返回的数据格式正确
                if (Array.isArray(result) && result.length > 0) {
                  console.log(
                    "生成名人卡片成功，共生成",
                    result.length,
                    "个卡片",
                  );
                  resolve(result);
                } else {
                  console.error(
                    "API返回的数据格式不正确，期望是数组但得到:",
                    result,
                  );
                  // 生成默认数据作为 fallback
                  console.log("使用默认数据作为fallback");
                  resolve(generateDefaultCelebrities());
                }
              } catch (parseError) {
                console.error("解析API响应失败:", parseError);
                // 生成默认数据作为 fallback
                console.log("使用默认数据作为fallback");
                resolve(generateDefaultCelebrities());
              }
            },
            (error) => {
              console.error("调用LLM API失败:", error);
              // 生成默认数据作为 fallback
              console.log("使用默认数据作为fallback");
              resolve(generateDefaultCelebrities());
            },
          );
        } else {
          console.error("window.sendToLLM函数不存在");
          // 生成默认数据作为 fallback
          console.log("使用默认数据作为fallback");
          resolve(generateDefaultCelebrities());
        }
      } catch (error) {
        console.error("调用LLM API失败:", error);
        // 生成默认数据作为 fallback
        console.log("使用默认数据作为fallback");
        resolve(generateDefaultCelebrities());
      }
    });
  };

  // 生成默认名人卡片数据（作为 fallback）
  const generateDefaultCelebrities = () => {
    const defaultCelebrities = [
      {
        id: Date.now() + 1,
        name: "新名人1",
        tagLine: "#热点话题人物",
        subTag: "#热议人物",
        avatarBg: "#F3E5F5",
        iconColor: "#9575CD",
        themeColor: "#F8F4FC",
      },
      {
        id: Date.now() + 2,
        name: "新名人2",
        tagLine: "#社会焦点",
        subTag: "#公众人物",
        avatarBg: "#E3F2FD",
        iconColor: "#2196F3",
        themeColor: "#F3F8FF",
      },
      {
        id: Date.now() + 3,
        name: "新名人3",
        tagLine: "#行业领袖",
        subTag: "#专业领域",
        avatarBg: "#E8F5E9",
        iconColor: "#4CAF50",
        themeColor: "#F1F8E9",
      },
    ];
    return defaultCelebrities;
  };

  // 自动轮播逻辑
  useEffect(() => {
    const startAutoPlay = () => {
      autoPlayRef.current = setInterval(() => {
        setActiveIndex((prev) => (prev + 1) % carouselData.length);
      }, 3000); // 3秒自动切换
    };

    startAutoPlay();

    return () => clearInterval(autoPlayRef.current);
  }, [carouselData.length]);

  const handleTouchStart = (e) => {
    touchStartY.current = e.touches[0].clientY;
    // 触摸时暂停轮播
    clearInterval(autoPlayRef.current);
  };

  const handleTouchEnd = (e) => {
    const touchEndY = e.changedTouches[0].clientY;
    const diff = touchStartY.current - touchEndY;

    if (Math.abs(diff) > 30) {
      if (diff > 0) {
        // 向上滑 (下一个)
        setActiveIndex((prev) => (prev + 1) % carouselData.length);
      } else {
        // 向下滑 (上一个)
        setActiveIndex(
          (prev) => (prev - 1 + carouselData.length) % carouselData.length,
        );
      }
    }

    // 触摸结束后重启轮播
    autoPlayRef.current = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % carouselData.length);
    }, 3000);
  };

  return (
    <div style={{ marginBottom: "24px" }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: "12px",
        }}
      >
        <h3 className="section-title">话题名人</h3>
        <button
          onClick={refreshCelebrities}
          disabled={isLoading}
          title={isLoading ? "正在生成话题名人..." : "刷新话题名人"}
          className={`active-press ${isLoading ? "animate-pulse" : ""}`}
          style={{
            width: "32px",
            height: "32px",
            borderRadius: "50%",
            background: isLoading
              ? "rgba(214, 114, 75, 0.15)"
              : "rgba(90, 95, 77, 0.08)",
            border: "none",
            cursor: isLoading ? "not-allowed" : "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: isLoading ? "#D6724B" : "#5a5f4d",
            transition: "all 0.25s ease",
          }}
        >
          <i
            className={`ph-bold ${isLoading ? "ph-spinner" : "ph-arrows-clockwise"}`}
            style={{
              fontSize: "16px",
              animation: isLoading ? "spin 1s linear infinite" : "none",
            }}
          ></i>
        </button>
      </div>
      <div
        className="carousel-container"
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
      >
        {carouselData.map((item, index) => {
          let offset = 0;
          let opacity = 1;
          let zIndex = 1;

          // 计算偏移逻辑，确保循环视觉效果
          // 简单的堆叠逻辑
          offset = 160;
          opacity = 0;

          return (
            <div
              key={item.id}
              className="carousel-card"
              style={{
                background: item.themeColor,
                transform: `translateY(${index === activeIndex ? 0 : index > activeIndex ? 160 : -160
                  }px)`,
                opacity: index === activeIndex ? 1 : 0,
                zIndex: index === activeIndex ? 10 : 1,
                pointerEvents: index === activeIndex ? "auto" : "none", // 防止点击看不见的卡片
              }}
            >
              <div className="avatar" style={{ background: item.avatarBg }}>
                <span
                  style={{
                    color: item.iconColor,
                    fontWeight: "bold",
                    fontSize: "20px",
                  }}
                >
                  B
                </span>
              </div>
              <div style={{ flex: 1 }}>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    marginBottom: "4px",
                  }}
                >
                  <span className="name">{item.name}</span>
                  <div style={{ transform: "rotate(0deg)" }}>
                    <T7Icons.ChevronDown />
                  </div>
                </div>
                <div className="tagline">{item.tagLine}</div>
                <div className="subtag">{item.subTag}</div>
              </div>
              <div className="carousel-controls">
                <div style={{ transform: "rotate(-90deg)", opacity: 0.3 }}>
                  <T7Icons.ChevronDown />
                </div>
                <div style={{ display: "flex", gap: "8px" }}>
                  <span style={{ fontSize: "12px", color: "#999" }}>
                    查看标签
                  </span>
                  <span
                    onClick={(e) => {
                      e.stopPropagation();
                      // 触发回调
                      if (onCharacterClick) onCharacterClick(item);
                    }}
                    style={{
                      fontSize: "12px",
                      color: "#999",
                      cursor: "pointer",
                      textDecoration: "underline",
                    }}
                  >
                    点击主页
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 指示器 */}
      <div className="indicators">
        {carouselData.map((_, idx) => (
          <div
            key={idx}
            className={`indicator ${idx === activeIndex ? "active" : ""}`}
          />
        ))}
      </div>
    </div>
  );
};

// T7 热点追踪列表
const HotTrackingList = ({ onPostClick }) => {
  // 从localStorage中获取缓存的区域内容
  const getHotPosts = () => {
    try {
      const hotPosts = [];
      // 遍历localStorage中的所有键
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        // 只处理区域内容缓存
        if (key && key.startsWith("area_content_")) {
          const cachedContent = localStorage.getItem(key);
          if (cachedContent) {
            try {
              const parsedContent = JSON.parse(cachedContent);
              // 提取帖子数据
              if (parsedContent.items && Array.isArray(parsedContent.items)) {
                parsedContent.items.forEach((item) => {
                  if (item.title && (item.likes || item.comments)) {
                    // 计算帖子的缓存键，与 PostDetailPage 中的逻辑一致
                    const contentHash = Array.from(
                      (item.title || "") + (item.content || ""),
                    ).reduce((acc, char) => acc + char.charCodeAt(0), 0);
                    const postCacheKey = `post_detail_${contentHash}`;

                    // 检查该帖子是否被用户打开过（是否存在对应的缓存）
                    const postCache = localStorage.getItem(postCacheKey);
                    if (postCache) {
                      // 计算热度分数（点赞数 + 评论数）
                      const hotScore = (item.likes || 0) + (item.comments || 0);
                      hotPosts.push({
                        id: item.id,
                        title: item.title,
                        hotScore: hotScore,
                        likes: item.likes || 0,
                        comments: item.comments || 0,
                        content: item.content || "",
                        date: item.date || "",
                        color: item.color || "",
                        areaContent: parsedContent, // 保存完整的区域内容
                      });
                    }
                  }
                });
              }
            } catch (error) {
              console.error("解析缓存内容失败:", error);
            }
          }
        }
      }

      // 按照热度分数排序
      hotPosts.sort((a, b) => b.hotScore - a.hotScore);

      return hotPosts;
    } catch (error) {
      console.error("获取热门帖子失败:", error);
      return [];
    }
  };

  // 获取热门帖子
  const hotPosts = getHotPosts();

  // 如果没有热门帖子，使用默认数据
  const listData =
    hotPosts.length > 0
      ? hotPosts.slice(0, 8).map((post, i) => ({
        ...post, // 保存完整的帖子数据
        views: post.hotScore.toLocaleString(),
        iconBg: i % 2 === 0 ? "#D8E6D8" : "#F0F0F0",
      }))
      : Array.from({ length: 8 }).map((_, i) => ({
        id: i,
        title: i === 0 ? "五年绣衣 三年特训" : `热门话题追踪 No.${i + 1}`,
        views: (28312.22 - i * 1000).toLocaleString("en-US", {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        }),
        iconBg: i % 2 === 0 ? "#D8E6D8" : "#F0F0F0",
      }));

  return (
    <div className="hotlist-container">
      <h3 className="section-title">热点追踪</h3>
      {/* 确保这里可以滚动，且不会因为父级重绘而重置位置 */}
      <div className="hotlist-scroll no-scrollbar">
        {listData.map((item, index) => (
          <div
            key={item.id}
            className="fade-in hot-item"
            style={{
              animationDelay: `${index * 0.05}s`,
              cursor: "pointer",
            }}
            onClick={() => {
              if (onPostClick && item.areaContent) {
                onPostClick(item);
              }
            }}
          >
            <div className="hot-icon" style={{ background: item.iconBg }}>
              <T7Icons.Leaf />
            </div>
            <div className="hot-title">{item.title}</div>
            <div className="hot-views">
              <T7Icons.Eye />
              <span
                style={{
                  fontSize: "14px",
                  marginLeft: "6px",
                  fontFamily: "Arial",
                }}
              >
                {item.views}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

