                  flex: 1,
                  padding: "8px 0",
                  borderRadius: "10px",
                  border: "none",
                  fontSize: "13px",
                  fontWeight: playSubTab === "fourArts" ? "700" : "500",
                  background: playSubTab === "fourArts" ? "#FFFFFF" : "transparent",
                  color: playSubTab === "fourArts" ? "#3B4235" : "#7B8072",
