  // ========== [新增] 加载和保存设置到IndexedDB ==========
  // 加载保存的设置
  React.useEffect(() => {
    const loadSettings = async () => {
      if (!chatData?.id) return;

      try {
        const db = await openDB();
        const transaction = db.transaction(STORES.USER_SETTINGS, "readonly");
        const store = transaction.objectStore(STORES.USER_SETTINGS);
        const request = store.get(`chat_settings_${chatData.id}`);

        request.onsuccess = () => {
          const savedSettings = request.result?.value;
          if (savedSettings) {
            setSettings((prev) => ({
              ...prev,
              ...savedSettings,
            }));
          }
        };
      } catch (error) {
        console.error("加载设置失败:", error);
      }
    };

    loadSettings();
  }, [chatData?.id]);

  // 保存设置到IndexedDB
  React.useEffect(() => {
    const saveSettings = async () => {
      if (!chatData?.id) return;

      try {
        const db = await openDB();
        const transaction = db.transaction(STORES.USER_SETTINGS, "readwrite");
        const store = transaction.objectStore(STORES.USER_SETTINGS);

        // 只保存需要持久化的设置，排除动态状态
        const settingsToSave = {
          plotMode: settings.plotMode,
          timeAware: settings.timeAware,
          proactiveReply: settings.proactiveReply,
          contextLimit: settings.contextLimit,
          showStatus: settings.showStatus,
          showThoughts: settings.showThoughts,
          backgroundOpacity: settings.backgroundOpacity,
          showAvatars: settings.showAvatars,
          mountedMemories: settings.mountedMemories, // [新增] 保存挂载记忆
        };

        await store.put({
          key: `chat_settings_${chatData.id}`,
          value: settingsToSave,
        });
      } catch (error) {
        console.error("保存设置失败:", error);
      }
    };

    // 延迟保存，避免频繁写入
    const timer = setTimeout(saveSettings, 500);
    return () => clearTimeout(timer);
  }, [settings, chatData?.id]);

