                            position: "absolute",
                            bottom: 0,
                            width: "100%",
                            background: "rgba(0,0,0,0.6)",
                            color: "#fff",
                            fontSize: "10px",
                            textAlign: "center",
                            padding: "2px 0",
                            borderBottomLeftRadius: "6px",
                            borderBottomRightRadius: "6px",
