                  // 2. 保存进 IndexedDB
                  if (window.chatHistoryStore) {
                    try {
                      await window.chatHistoryStore.saveMessages(newGroupId, [
                        sysMsg,
                      ]);
                    } catch (e) {
                      console.error("保存群聊初始化消息失败", e);
                    }
                  }

                  setShowGroupMemberModal(false);
                  // 统一复用已存在的聊天详情层，不再依赖 isGroupChatOpen
                  setActiveChatId(newGroupId);
