// ==================== 世界书 (World Book) 组件群 START ====================

// 获取全局世界书上下文的工具函数 (供 AI 调用)
window.getWorldBookContext = async () => {
  try {
    const worldBookStore = window.worldBookStore;
    if (!worldBookStore) {
      console.log("世界书：worldBookStore 未初始化");
      return "";
    }

    const data = await worldBookStore.getData();
    if (!data || !data.books) {
      console.log("世界书：无数据");
      return "";
    }

    const entries = data.books;
    // 过滤出已启用的条目
    const activeEntries = entries.filter((e) => e.enable);
    console.log("世界书：已启用条目数量", activeEntries.length);
    console.log("世界书：已启用条目", activeEntries);
    if (activeEntries.length === 0) {
      console.log("世界书：无已启用条目");
      return "";
    }

    // 格式化为 Prompt
    const context = activeEntries
      .map((e) => `【设定：${e.title}】\n内容：${e.content}`)
      .join("\n\n");
    console.log("世界书：生成的上下文", context);
    return context;
  } catch (e) {
    console.error("读取世界书失败", e);
    return "";
  }
};

const WorldBookPage = () => {
  const { useState, useEffect } = React;

  // 数据结构: { id, title, content, enable: boolean }
  const [entries, setEntries] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null); // null = 新增模式

  // 表单状态
  const [formTitle, setFormTitle] = useState("");
  const [formContent, setFormContent] = useState("");

  // 初始化加载
  useEffect(() => {
    const loadWorldBookData = async () => {
      try {
        const worldBookStore = window.worldBookStore;
        if (worldBookStore) {
          const data = await worldBookStore.getData();
          if (data && data.books) {
            setEntries(data.books);
          } else {
            // 默认示例数据
            const defaults = [
              {
                id: 1,
                title: "东汉时期考",
                content:
                  "汉末乱世，天子设绣衣楼于广陵，掌管天下情报与机密。楼主手握重权，亦是各方势力觊觎的焦点。",
                enable: true,
              },
              {
                id: 2,
                title: "角色：广陵王",
                content:
                  "玩家扮演的角色，女扮男装的广陵亲王，兼任绣衣楼楼主。性格隐忍坚毅，心思缜密。",
                enable: true,
              },
            ];
            setEntries(defaults);
            await worldBookStore.saveData({ books: defaults });
          }
        } else {
          console.error("worldBookStore 未初始化");
        }
      } catch (e) {
        console.error("加载世界书数据失败:", e);
      }
    };

    loadWorldBookData();
  }, []);

  // 保存数据到IndexedDB
  const saveToLocal = async (data) => {
    setEntries(data);
    try {
      const worldBookStore = window.worldBookStore;
      if (worldBookStore) {
        await worldBookStore.saveData({ books: data });
        console.log("世界书数据保存到IndexedDB成功");
      } else {
        console.error("worldBookStore 未初始化");
      }
    } catch (e) {
      console.error("保存世界书数据失败:", e);
    }
  };

  // 切换开关状态
  const toggleEntry = (id) => {
    const newData = entries.map((item) =>
      item.id === id ? { ...item, enable: !item.enable } : item,
    );
    saveToLocal(newData);
    // 震动反馈
    if (navigator.vibrate) navigator.vibrate(5);
  };

  // 打开模态框
  const openModal = (item = null) => {
    if (item) {
      setEditingId(item.id);
      setFormTitle(item.title);
      setFormContent(item.content);
    } else {
      setEditingId(null);
      setFormTitle("");
      setFormContent("");
    }
    setIsModalOpen(true);
  };

  // 提交表单
  const handleSubmit = () => {
    if (!formTitle.trim() || !formContent.trim()) {
      alert("标题和内容不能为空");
      return;
    }

    let newData;
    if (editingId) {
      // 编辑模式
      newData = entries.map((item) =>
        item.id === editingId
          ? { ...item, title: formTitle, content: formContent }
          : item,
      );
    } else {
      // 新增模式
      const newItem = {
        id: Date.now(),
        title: formTitle,
        content: formContent,
        enable: true, // 新增默认开启
      };
      newData = [newItem, ...entries];
    }

    saveToLocal(newData);
    setIsModalOpen(false);
  };

  // 删除条目
  const handleDelete = () => {
    if (confirm("确定要删除这条设定吗？")) {
      const newData = entries.filter((e) => e.id !== editingId);
      saveToLocal(newData);
      setIsModalOpen(false);
    }
  };

  return (
    <div
      style={{
        flex: 1,
        overflowY: "auto",
        padding: "20px",
        background: "#f5f6f8",
      }}
    >
      {/* 顶部说明 */}
      <div
        style={{
          padding: "12px 16px",
          background: "#E8F4FF",
          borderRadius: "12px",
          marginBottom: "20px",
          color: "#4A90E2",
          fontSize: "13px",
          lineHeight: "1.4",
        }}
      >
        <i
          className="ph-fill ph-info"
          style={{ verticalAlign: "middle", marginRight: "4px" }}
        ></i>
        开启的条目将自动作为“全局记忆”注入到所有 AI
        对话中。请管理好您的世界观设定。
      </div>

      {/* 列表区域 */}
      {entries.length === 0 ? (
        <div
          style={{
            textAlign: "center",
            padding: "40px 0",
            color: "#999",
          }}
        >
          暂无设定，点击右下角添加
        </div>
      ) : (
        <div style={{ paddingBottom: "80px" }}>
          {entries.map((item) => (
            <div
              key={item.id}
              className={`wb-card ${item.enable ? "active" : ""}`}
            >
              <div className="wb-header">
                <div
                  className="wb-title"
                  onClick={() => openModal(item)}
                  style={{ cursor: "pointer", flex: 1 }}
                >
                  {item.title}
                </div>
                {/* 阻断冒泡，防止点击开关触发编辑 */}
                {/* [修改] 添加 marginRight: "15px" 让按钮往左挪一点，不再紧贴右边缘 */}
                <div
                  onClick={(e) => e.stopPropagation()}
                  style={{ marginRight: "15px" }}
                >
                  <label className="toggle-switch">
                    <input
                      type="checkbox"
                      className="toggle-input"
                      checked={item.enable}
                      onChange={() => toggleEntry(item.id)}
                    />
                    <span className="toggle-slider"></span>
                  </label>
                </div>
              </div>
              <div className="wb-content" onClick={() => openModal(item)}>
                {item.content}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 悬浮添加按钮 */}
      <button
        onClick={() => openModal(null)}
        style={{
          position: "absolute",
          bottom: "30px",
          right: "20px",
          width: "56px",
          height: "56px",
          borderRadius: "50%",
          background: "#4A90E2",
          color: "white",
          border: "none",
          boxShadow: "0 4px 15px rgba(74, 144, 226, 0.4)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: "24px",
          cursor: "pointer",
          zIndex: 10,
        }}
      >
        <i className="ph-bold ph-plus"></i>
      </button>

      {/* 编辑/新增 模态框 */}
      <div className={`wb-modal ${isModalOpen ? "show" : ""}`}>
        <div className="wb-modal-content">
          <h3
            style={{
              fontSize: "18px",
              fontWeight: "bold",
              marginBottom: "16px",
              color: "#333",
            }}
          >
            {editingId ? "编辑设定" : "新建设定"}
          </h3>

          <div style={{ marginBottom: "16px" }}>
            <label
              style={{
                display: "block",
                fontSize: "12px",
                color: "#999",
                marginBottom: "4px",
              }}
            >
              标题 / 关键词
            </label>
            <input
              type="text"
              value={formTitle}
              onChange={(e) => setFormTitle(e.target.value)}
              placeholder="例如：魔法系统、角色关系..."
              style={{
                width: "100%",
                padding: "10px",
                borderRadius: "8px",
                border: "1px solid #eee",
                fontSize: "15px",
                outline: "none",
              }}
            />
          </div>

          <div style={{ marginBottom: "24px" }}>
            <label
              style={{
                display: "block",
                fontSize: "12px",
                color: "#999",
                marginBottom: "4px",
              }}
            >
              设定内容
            </label>
            <textarea
              value={formContent}
              onChange={(e) => setFormContent(e.target.value)}
              placeholder="详细描述这个设定，AI将读取这些内容..."
              style={{
                width: "100%",
                height: "120px",
                padding: "10px",
                borderRadius: "8px",
                border: "1px solid #eee",
                fontSize: "14px",
                resize: "none",
                outline: "none",
                lineHeight: "1.5",
              }}
            />
          </div>

          <div style={{ display: "flex", gap: "10px" }}>
            {editingId && (
              <button
                onClick={handleDelete}
                style={{
                  padding: "10px 16px",
                  borderRadius: "8px",
                  border: "none",
                  background: "#FFECEC",
                  color: "#FF6B6B",
                  fontWeight: "500",
                }}
              >
                删除
              </button>
            )}

            <button
              onClick={() => setIsModalOpen(false)}
              style={{
                flex: 1,
                padding: "10px",
                borderRadius: "8px",
                border: "1px solid #eee",
                background: "white",
                color: "#666",
              }}
            >
              取消
            </button>
            <button
              onClick={handleSubmit}
              style={{
                flex: 1,
                padding: "10px",
                borderRadius: "8px",
                border: "none",
                background: "#4A90E2",
                color: "white",
                fontWeight: "500",
              }}
            >
              保存
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

