  // ==================== 新增：收益捐相关状态与逻辑 END ====================

  useEffect(() => {
    const savedSubs = JSON.parse(
      localStorage.getItem("charity_monthly_subs") || "[]",
    );

    let needsUpdate = false;
    let currentBalance = parseInt(localStorage.getItem("farm_coins") || "500");
    const today = new Date();

    const updatedSubs = savedSubs.map((sub) => {
      const nextDate = new Date(sub.nextDeductDate);
      if (today >= nextDate) {
        if (currentBalance >= sub.amount) {
          currentBalance -= sub.amount;
          if (window.addTransactionRecord) {
            window.addTransactionRecord(
              "expense",
              sub.amount,
              `月捐自动扣款：${sub.projectName}`,
            );
          }
          nextDate.setMonth(nextDate.getMonth() + 1);
          needsUpdate = true;
          return {
            ...sub,
            nextDeductDate: nextDate.toISOString().split("T")[0],
          };
        }
      }
      return sub;
    });

    if (needsUpdate) {
      localStorage.setItem("farm_coins", currentBalance.toString());
      localStorage.setItem("charity_monthly_subs", JSON.stringify(updatedSubs));
    }
    setMonthlySubscriptions(updatedSubs);
  }, []);

