  // 2. 获取音乐播放链接、歌词，并添加到播放列表
  const handleAddOnlineSong = async (song) => {
    try {
      alert("正在解析音乐链接和歌词，请稍候...");

      // 获取播放URL
      const urlRes = await fetch(
        `https://music-api.gdstudio.xyz/api.php?types=url&source=${song.source}&id=${song.id}`,
      );
      const urlData = await urlRes.json();

      if (!urlData.url) {
        alert("无法获取该歌曲的播放链接，可能受版权限制！");
        return;
      }

      // 获取歌词
      let parsedLyrics = [{ time: 0, text: "纯音乐 / 无歌词" }];
      try {
        const lrcRes = await fetch(
          `https://music-api.gdstudio.xyz/api.php?types=lyric&source=${song.source}&id=${song.lyric_id || song.id}`,
        );
        const lrcData = await lrcRes.json();
        if (lrcData.lyric) {
          parsedLyrics = parseLRC(lrcData.lyric);
        }
      } catch (e) {
        console.error("获取歌词失败", e);
      }

      // 格式化歌手名字
      const artistName = Array.isArray(song.artist)
        ? song.artist.join("/")
        : song.artist;

      // 组装新歌曲对象
      const newSong = {
        id: `online_${song.id}_${Date.now()}`,
        title: `${song.name} - ${artistName}`,
        audioSrc: urlData.url,
        lyrics: parsedLyrics,
        isFav: false,
      };

      // 添加到列表并自动播放
      setPlaylist((prev) => [...prev, newSong]);
      setCurrentSongId(newSong.id);
      setIsPlaying(true);
      setShowMusicSearch(false); // 关闭搜索弹窗

      // 保存到 IndexedDB
      if (window.musicStore) {
        window.musicStore.save(newSong);
      }
    } catch (e) {
      console.error(e);
      alert("添加歌曲发生错误");
    }
  };
  // ==============================================================

  // 1. 解析 LRC (保持不变)
  const parseLRC = (lrcString) => {
    // 兼容 Windows(\r\n) 和 Linux/Mac(\n) 换行符
    const lines = lrcString.split(/\r?\n/);
    const result = [];
    // 正则增强：匹配 [00:00.00] 或 [00:00.000] 或 [00:00]
    const timeExp = /\[(\d{2,}):(\d{2})(?:\.(\d{2,3}))?\]/;

    let hasTimeTags = false;

    lines.forEach((line) => {
      const match = timeExp.exec(line);
      if (match) {
        hasTimeTags = true;
        const minutes = parseInt(match[1], 10);
        const seconds = parseInt(match[2], 10);
        const milliseconds = match[3] ? parseInt(match[3], 10) : 0;
        const ms =
          match[3] && match[3].length === 2 ? milliseconds * 10 : milliseconds;

        const time = minutes * 60 + seconds + ms / 1000;
        const text = line.replace(timeExp, "").trim();
        if (text) result.push({ time, text });
      }
    });

    // 【修复 4】如果是纯TXT文本(没有任何时间标签)，为它自动分配伪时间使其成为滚动面板
    if (!hasTimeTags) {
      let fakeTime = 0;
      lines.forEach((line) => {
        if (line.trim()) {
          result.push({ time: fakeTime, text: line.trim() });
          fakeTime += 3; // 假设每行唱3秒
        }
      });
    }

    result.sort((a, b) => a.time - b.time);
    return result.length > 0 ? result : [{ time: 0, text: "纯音乐 / 无歌词" }];
  };

  // 2. 上传音乐 -> 加入播放列表
  const handleMusicUpload = async (e) => {
    const file = e.target.files[0];
    if (file) {
      const newSong = {
        id: `local_${Date.now()}`,
        title: file.name.replace(/\.[^/.]+$/, ""),
        audioBlob: file, // 保存二进制Blob文件用于持久化
        audioSrc: URL.createObjectURL(file), // 内存链接，刷新即销毁
        lyrics: [{ time: 0, text: "暂无歌词，请在列表中添加" }],
        isFav: false,
      };

      setPlaylist((prev) => [...prev, newSong]);
      if (playlist.length === 0) setCurrentSongId(newSong.id);

      // 保存到 IndexedDB
      if (window.musicStore) {
        await window.musicStore.save(newSong);
      }

      if (confirm(`《${newSong.title}》添加成功！是否立即上传歌词？`)) {
        lyricUpdateTargetId.current = newSong.id;
        lyricInputRef.current.click();
      }
    }
    e.target.value = "";
  };

  // 3. 上传/更新歌词
  const handleLyricUpload = (e) => {
    const file = e.target.files[0];
    if (file && lyricUpdateTargetId.current) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const parsed = parseLRC(event.target.result);
        let updatedSong = null;

        setPlaylist((prev) =>
          prev.map((song) => {
            if (song.id === lyricUpdateTargetId.current) {
              updatedSong = { ...song, lyrics: parsed };
              return updatedSong;
            }
            return song;
          }),
        );

        // 同步歌词到 IndexedDB
        if (updatedSong && window.musicStore) {
          window.musicStore.save(updatedSong);
        }

        alert("歌词更新成功！");
        lyricUpdateTargetId.current = null;
      };
      reader.readAsText(file);
    }
    e.target.value = "";
  };

  // 4. 操作函数
  const toggleFav = (id) => {
    let updatedSong = null;
    setPlaylist((prev) =>
      prev.map((s) => {
        if (s.id === id) {
          updatedSong = { ...s, isFav: !s.isFav };
          return updatedSong;
        }
        return s;
      }),
    );
    // 同步收藏状态
    if (updatedSong && window.musicStore) {
      window.musicStore.save(updatedSong);
    }
  };
  const deleteSong = (id) => {
    if (confirm("确定删除这首歌吗？")) {
      setPlaylist((prev) => prev.filter((s) => s.id !== id));
      if (currentSongId === id) {
        setIsPlaying(false);
        setCurrentSongId(null);
      }
      // 从 IndexedDB 中删除
      if (window.musicStore) {
        window.musicStore.delete(id);
      }
    }
  };
  const playNext = () => {
    if (!currentSongId || playlist.length === 0) return;
    // 简单逻辑：按列表顺序下一首，找不到就停
    const currentIndex = playlist.findIndex((s) => s.id === currentSongId);
    const nextSong = playlist[currentIndex + 1] || playlist[0]; // 循环播放
    if (nextSong) {
      setCurrentSongId(nextSong.id);
      setIsPlaying(true);
    }
  };

  // 5. 获取当前播放对象
  const currentSong = playlist.find((s) => s.id === currentSongId) || {
    title: "请添加音乐",
    lyrics: [{ time: 0, text: "点击右侧 + 号上传音乐" }],
  };

  // 6. 歌词索引计算
  const getActiveLyricIndex = () => {
    if (!currentSong.lyrics || currentSong.lyrics.length === 0) return 0;

    // 【修复 3】核心BUG：当前时间还没达到第一句歌词的时间时，强制显示第0句，而不是跳到最后一句
    if (currentTime < currentSong.lyrics[0].time) return 0;

    for (let i = 0; i < currentSong.lyrics.length - 1; i++) {
      if (
        currentTime >= currentSong.lyrics[i].time &&
        currentTime < currentSong.lyrics[i + 1].time
      ) {
        return i;
      }
    }
    return currentSong.lyrics.length - 1;
  };
  const activeLyricIdx = getActiveLyricIndex();

  // 7. 播放控制 Effect
  useEffect(() => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.play().catch(() => setIsPlaying(false));
      } else {
        audioRef.current.pause();
      }
    }
  }, [isPlaying, currentSongId]); // 切歌时自动播放

  // 8. 歌词自动滚动 Effect
