    showPlaylist, // 关键：面板开关时刷新
    showMusicSearch, // <-- 【新增这一行】搜索弹窗开关时刷新图标
    musicSearchResults, // <-- 【新增这一行】搜索结果更新时刷新图标
    isReaderOpen,
    isForumOpen,
    isMsgOpen,
    isT9Open,
    isT10Open,
    isT11Open,
    isT12Open,
    isT13Open,
    isAPISettingsOpen,
