          {/* [新增] AI 荐书悬浮组件 - 只在今日阅读时显示 */}
          {currentReaderTab === "today" && (
            <AIBookRecommender
              books={books}
              onConfirm={async (book) => {
                // 这里复用原本“开始阅读”按钮的逻辑
                if (!book) return;

                // 尝试读取全文
                let content = null;

                // 优先从IndexedDB获取书籍内容
                if (window.bookStore) {
                  try {
                    content = await window.bookStore.getContent(book.id);
                    console.log("从IndexedDB获取书籍内容成功:", book.id);
                  } catch (error) {
                    console.error("从IndexedDB获取书籍内容失败:", error);
                  }
                }

                // 如果IndexedDB中没有，尝试从localStorage获取
                if (!content) {
                  content = localStorage.getItem(`book_content_${book.id}`);
                  if (content) {
                    console.log("从localStorage获取书籍内容成功:", book.id);
                  }
                }

                // 如果都没有，使用默认内容
                if (!content) {
                  if (book.fullText) content = book.fullText;
                  else content = "预设书籍内容...";
                }

                const bookToRead = { ...book, fullText: content };

                setCurrentReadingBook(bookToRead);
                setIsReadingDetailOpen(true);
              }}
            />
          )}

          {/* 底部按钮区 - 只在今日阅读时显示 */}
